    inv.lines.forEach(l=>{ if(l.service){ if(!missed.length||l.haulAway) l.deliveredAt=todayISO(); return; } if(taken.includes(l)) l.deliveredAt=todayISO(); });
    const remaining=inv.lines.filter(l=>!l.service&&!l.deliveredAt);
    if(remaining.length){ remaining.forEach(l=>{ if(missed.includes(l)&&!l.special){ l.delayReason=l.delayReason||"Not delivered on first trip"; } }); const c=byId("customers",inv.customerId); follow=await save("deliveries",{id:uid(),invoiceId:inv.id,customerId:inv.customerId,date:"",winStart:d.winStart,winEnd:d.winEnd,truckId:"",status:remaining.every(lineBlocked)?"awaiting":"unscheduled",order:0,notes:(c?.notes?c.notes+" · ":"")+"Remaining from "+dateShort(d.deliveredAt)+": "+remaining.map(l=>l.qty+"× "+l.name).join(", "),lineIds:remaining.map(l=>l.lineId),haulAway:0,setup:d.setup,followsId:d.id}); }
    await save("invoices",inv);
    if(!remaining.length){ await addFollowup(inv.customerId,inv.id,"Delivery check-in","Make sure everything arrived in good shape and they're happy.",addDays(todayISO(),3)); await addFollowup(inv.customerId,inv.id,"Review request","Ask for a review.",addDays(todayISO(),14)); }
    if(inv.lines.some(l=>l.mattress&&l.trial&&taken.includes(l))) await addFollowup(inv.customerId,inv.id,"Sleep trial ending soon","Check in before the comfort trial ends.",addDays(todayISO(),Math.max(7,st.trialNights-14)));
