function applyRoleDefaults(role){ const d=ROLE_PERMS[role]||{}; document.querySelectorAll(".s_perm").forEach(e=>{ e.checked=!!d[e.dataset.k]; }); }
async function saveStaff(id){ if(!requirePerm("staff","change staff or permissions")) return; { const before=id?byId("staff",id):null; const newRole=fv("s_role"); const touchesMgmt=["manager","owner"].includes(newRole)||(before&&["manager","owner"].includes(before.role)); if(touchesMgmt&&!has("manageManagers")) return denied("add or change managers and owners — that's reserved for the store owner"); if(newRole==="owner"&&!isOwner()) return denied("assign the owner role"); } if(id&&id===session.staffId&&!has("approve")) return denied("change your own permissions"); { const before=byId("staff",id); logAudit("staff",`${before?"Edited":"Added"} ${fv("s_name")||(before&&before.name)||""} (role ${fv("s_role")})${before&&fv("s_pin")&&String(before.pin)!==fv("s_pin")?" · PIN changed":""}`); } const role=fv("s_role"); const d=ROLE_PERMS[role]||{}; const perms={}; document.querySelectorAll(".s_perm").forEach(e=>{ const k=e.dataset.k; if(!!e.checked!==!!d[k]) perms[k]=e.checked; }); const limits={}; if(fv("s_maxdisc")!=="") limits.maxDiscountPct=fnum("s_maxdisc"); if(fv("s_minmargin")!=="") limits.minMarginPct=fnum("s_minmargin"); const x=Object.assign({},byId("staff",id)||{},{id:id||undefined,name:fv("s_name").trim(),role,pin:fv("s_pin").trim(),commType:fv("s_type"),rate:fnum("s_rate"),planRate:fv("s_planrate")===""?"":fnum("s_planrate"),lang:fv("s_lang")||"",active:fchk("s_active"),perms,limits}); if(!x.name) return toast("Name is required.",true); if(x.pin&&!/^\d{4,8}$/.test(x.pin)) return toast("PIN must be 4–8 digits.",true); if(id===session.staffId&&x.role!=="manager"&&role()==="manager"&&S.staff.filter(s=>s.role==="manager"&&s.id!==id).length===0) return toast("Keep at least one manager.",true); if(x.role==="manager"&&x.perms.approve===false&&!S.staff.some(s=>s.id!==id&&s.role==="manager")) delete x.perms.approve; await save("staff",x); closeModal(); render(); }
function restoreBackup(){ modal(`<h2>Restore backup</h2><p class="muted">Paste the contents of a pos-backup file. This replaces all current data.</p><textarea id="bk" rows="10"></textarea><div class="actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn p" onclick="doRestore()">Restore</button></div>`); }
async function doRestore(){ let o; try{ o=JSON.parse(fv("bk")); if(!o.products) throw 0; }catch(e){ return toast("That doesn't look like a backup file.",true); } await wipe(false); for(const c of COLLS) for(const d of (o[c]||[])) await save(c,d); closeModal(); render(); toast("Backup restored"); }
async function wipe(rerender=true){ for(const c of COLLS){ for(const d of S[c].slice()) await remove(c,d.id); } if(rerender){ toast("Store data erased"); logout(); } }

