/* next N delivery days with their load — for one-tap scheduling */
function nextDeliveryDays(n){ const st=storeSettings(); const days=st.deliveryDays&&st.deliveryDays.length?st.deliveryDays:[1,2,3,4,5,6]; const out=[]; let d=todayISO(); let guard=0; while(out.length<n&&guard<40){ const dow=new Date(d+"T12:00:00").getDay(); if(days.includes(dow)){ const L=dayLoad(d); out.push({date:d,label:new Date(d+"T12:00:00").toLocaleDateString(undefined,{weekday:"short",month:"short",day:"numeric"}),stops:L.stops,maxStops:L.maxStops,load:L.load}); } d=addDays(d,1); guard++; } return out; }
